import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// The log whispers of mocks...
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Owl Figurine', price: 29.99 },
  { id: '2', name: 'Damn Fine Coffee', price: 12.50 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockItems,
    total: 42.49,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The log sees all paths', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Happy Path - The straight path through the woods', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });

      render(<Checkout onComplete={onComplete} />);

      // Shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Twin Peaks Rd');
      await user.type(screen.getByLabelText(/city/i), 'Twin Peaks');
      await user.selectOptions(screen.getByLabelText(/state/i), 'WA');
      await user.type(screen.getByLabelText(/zip code/i), '98045');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Dale Cooper');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review & Submit
      expect(screen.getByText(/\$42\.49/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/ORD-12345/)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Validation - The log warns of errors', () => {
    it('shows error when ZIP code format is invalid', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    });
  });

  describe('Empty Cart - The void speaks', () => {
    it('displays empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Payment Failure - Darkness in the woods', () => {
    it('displays error and allows retry when payment fails', async () => {
      const user = userEvent.setup();
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));

      // ... navigate to review step ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Accessibility - The log judges not, but observes', () => {
    it('has no accessibility violations on shipping step', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
